import { readdir, readFile, writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const appsDirectory = path.join(root, "apps");
const outputPath = path.join(root, "dapp-web", "bundled-apps.js");
const checkOnly = process.argv.includes("--check");
const firmwareSeedSource = await readFile(path.join(root, "BundledApps.ino"), "utf8");

const filenames = (await readdir(appsDirectory))
  .filter(filename => filename.endsWith(".dapp"))
  .sort((a, b) => a.localeCompare(b));

const apps = {};
for (const filename of filenames) {
  const id = filename.slice(0, -5);
  apps[id] = { source: await readFile(path.join(appsDirectory, filename), "utf8") };
}

const firmwareAppIds = [...firmwareSeedSource.matchAll(/"\/system\/apps\/([a-z0-9-]+)\.dapp"/g)]
  .map(match => match[1]);
for (const id of firmwareAppIds) {
  if (!apps[id]) throw new Error(`BundledApps.ino references missing apps/${id}.dapp`);
}
const firmwareApps = Object.fromEntries(firmwareAppIds.map(id => [id, apps[id]]));

const generated = `// Generated by tools/build-web-app-bundle.mjs. Do not edit by hand.\nexport const bundledApps = Object.freeze(${JSON.stringify(firmwareApps, null, 2)});\nexport const firmwareAppIds = Object.freeze(${JSON.stringify(firmwareAppIds)});\n`;

if (checkOnly) {
  let current = "";
  try { current = await readFile(outputPath, "utf8"); } catch {}
  if (current !== generated) {
    console.error("dapp-web/bundled-apps.js is out of date; run node tools/build-web-app-bundle.mjs");
    process.exitCode = 1;
  }
} else {
  await writeFile(outputPath, generated);
  console.log(`Wrote ${path.relative(root, outputPath)} with ${firmwareAppIds.length} firmware apps (${filenames.length} repository sources validated).`);
}
